<template>
  <a-modal
    v-drag-modal
    :title="$t('workflow.model.title.userInfo')"
    :visible="revisePasswordModalVisible"
    :keyboard="false"
    @cancel="handleReviseCancel"
    :cancelText="$t('common.btn.close')">
    <a-list :data-source="userData">
      <template v-for="(user, index) in userData">
        <a-list-item :key="index">
          {{ user.username }} {{ user.name }}
        </a-list-item>
      </template>
    </a-list>
    <template slot="footer">
      <a-button @click="handleReviseCancel">{{ $t('common.btn.close') }}</a-button>
    </template>
  </a-modal>
</template>

<script>
import {getWorkFlowUserByRoleIds} from '@/api/system/user/user'

    export default {
        name: 'RoleUserDetail',
        data () {
            return {
                userData: [],
                revisePasswordModalVisible: false,
                queryParam: {
                    roleIds: '',
                    corpId: ''
                }
            }
        },
        async beforeRouteEnter (to, from, next) {
            next()
        },
        methods: {
            async showModal (role) {
                const that = this
                that.revisePasswordModalVisible = true
                that.listUserByRoleId(role)
            },
            handleReviseCancel () {
                this.revisePasswordModalVisible = false
            },
            /**
             * 查询角色下员工信息
             */
            listUserByRoleId (role) {
                this.queryParam.roleIds = []
                this.queryParam.roleIds[0]=role.id
                this.queryParam.corpId = role.corpId
                const requestParameters = Object.assign({}, this.queryParam)
              getWorkFlowUserByRoleIds(requestParameters).then((response) => {
                    if (response.success) {
                        this.userData = response.obj
                    }
                })
            }
        }
    }
</script>
