<template>
  <a-modal
    v-drag-modal
    v-model="visible"
    :title="$t('workflow.model.label.sequential.flow.condition')"
    :width="700"
    :maskClosable="false"
    :destroyOnClose="true"
  >
    <div style="max-height: 50vh; overflow: auto">
      <a-form v-show="visible" :form="form" class="custom-design-form">
        <template v-for="(group, gIndex) in customSearchData">
          <div :key="'group' + gIndex" class="custom-search-group">
            <a-button
              class="symbolbtn"
              @click="group.leftBracket2 = !group.leftBracket2"
              :type="group.leftBracket2 ? 'primary' : 'default'"
              >{{ group.leftBracket2 ? "(" : "" }}
            </a-button>
            <a-button
              class="symbolbtn"
              @click="group.leftBracket1 = !group.leftBracket1"
              :type="group.leftBracket1 ? 'primary' : 'default'"
              >{{ group.leftBracket1 ? "(" : "" }}
            </a-button>
            <KFormItem
              :formConfig="formConfig"
              @change="
                (v, k) => {
                  group.fieldName = v
                  fieldNameChange(gIndex)
                }
              "
              :record="
                getFieldNameConfig({
                  gIndex,
                  defaultValue: group.fieldName,
                })
              "
            />
            <template v-if="group.selectType === '2'">
              <div>{{ JSON.stringify(group) }}</div>
              <!-- <a-select v-model="group.fieldValue" style="width: 200px">
                <a-select-option
                  :value="item.value"
                  v-for="item in group.options"
                  :key="item.value"
                  >{{ item.text }}</a-select-option
                >
              </a-select> -->
            </template>
            <template v-else>
              <!-- Relation -->
              <KFormItem
                class="group-relation"
                :formConfig="formConfig"
                @change="
                  (v, k) => {
                    group.relation = v
                    relationChange(gIndex)
                  }
                "
                :record="
                  getRelationConfig({
                    gIndex,
                    defaultValue: group.relation,
                    group,
                  })
                "
              />
              <!-- fieldValue -->
              <KFormItem
                style="min-width: 200px"
                :formConfig="formConfig"
                @change="
                  (v, k) => {
                    group.fieldValue = v
                  }
                "
                :dynamicData="dynamicData"
                :record="
                  getFieldValueConfig({
                    gIndex,
                    defaultValue: group.fieldValue,
                    group,
                  })
                "
              />
            </template>
            <!-- <KFormItem :formConfig="formConfig"  /> -->
            <a-button
              class="symbolbtn right-symbol"
              @click="group.rightBracket1 = !group.rightBracket1"
              :type="group.rightBracket1 ? 'primary' : 'default'"
              >{{ group.rightBracket1 ? ")" : "" }}
            </a-button>
            <a-button
              class="symbolbtn right-symbol"
              @click="group.rightBracket2 = !group.rightBracket2"
              :type="group.rightBracket2 ? 'primary' : 'default'"
              >{{ group.rightBracket2 ? ")" : "" }}
            </a-button>
            <a-button
              shape="circle"
              type="danger"
              icon="minus"
              :disabled="customSearchData.length === 1"
              ghost
              @click="delGroupItem(gIndex)"
              :title="$t('common.btn.delete')"
              size="small"
            ></a-button>
          </div>
          <div :key="'groupcondition' + gIndex" class="group-condition">
            <KFormItem
              v-if="gIndex !== customSearchData.length - 1"
              :key="`item-condition-'${gIndex}`"
              :formConfig="formConfig"
              :record="
                getConditionConfig({ gIndex, defaultValue: group.condition })
              "
            />
          </div>
        </template>
      </a-form>
    </div>
    <div slot="footer">
      <a-button icon="plus" @click="addGroup">
        <!--          {{ $t('common.btn.add') }}-->
      </a-button>
      <a-button type="default" @click="cancelPropertyConditions">{{
        $t("common.btn.cancel")
      }}</a-button>
      <a-button type="primary" @click="handleOk">{{
        $t("common.btn.save")
      }}</a-button>
    </div>
  </a-modal>
</template>

<script>
// import cloneDeep from 'lodash.clonedeep'
import baseConfigs, { getBaseSelectConfig } from "@/utils/formDesignBaseConfig"
import { listFlowCondition } from "@/api/workflow/option"
import { i18nRender } from "@/locales"

const conditionOptions = [
  { value: "and", label: "并且" },
  { value: "or", label: "或者" },
]
const relationBaseOptions = [
  { value: "contains", title: "i18n:common.filed.contain" },
  { value: "notContains", title: "i18n:common.filed.notContain" },
  { value: "eq", title: "=" },
  { value: "neq", title: "!=" },
  { value: "gt", title: ">" },
  { value: "geq", title: ">=" },
  { value: "lt", title: "<" },
  { value: "leq", title: "<=" },
  { value: "between", title: "i18n:common.filed.between" },
]
const conditionsMap = new Map()
conditionOptions.map((item) => {
  conditionsMap.set(item.value, item.label)
})
relationBaseOptions.map((item) => {
  conditionsMap.set(item.value, item.title)
})

// 初始化字典数据
function initDictOptions(options) {
  options.map((item) => {
    item.label = item.text
  })
  return options
}
/**
 * 新增一组时的默认数据
 */
function getBaseGroupValue() {
  return {
    leftBracket1: false,
    leftBracket2: false,
    rightBracket1: false,
    rightBracket2: false,
    condition: "and",
    fieldName: null,
    relation: "",
    fieldValue: "",
  }
}

/**
 * 检测括号逻辑
 */
function checkBrackets(datas) {
  let start = 0
  for (let i = 0; i < datas.length; i++) {
    if (start < 0) break
    const element = datas[i]
    if (element.leftBracket1) start = start + 1
    if (element.leftBracket2) start = start + 1
    if (element.rightBracket1) start = start - 1
    if (element.rightBracket2) start = start - 1
  }
  return start === 0
}

export default {
  name: "PropertyFlowConditions",
  props: {
    workflowModel: {
      type: Object,
      required: false,
      default: () => {},
    },
    // columns: {
    //     type: Array,
    //     required: true,
    //     default: () => []
    // },
    // eslint-disable-next-line vue/require-default-prop
    // formItemConfigs: {
    //     type: Object,
    //     default: () => ({})
    // },
    dynamicData: {
      type: Object,
      default: () => ({}),
    },
  },
  data() {
    return {
      formConfig: {},
      element: null,
      form: this.$form.createForm(this), // async from
      // customPropertyConditions: [getBaseGroupValue()],
      customSearchData: [getBaseGroupValue()], // 自定义搜索数据
      visible: false,
      modalVisible: false,
      flowConditions: [],
      columns: [],
      formItemConfigs: {}, // 表单配置
    }
  },
  computed: {
    fieldNameOptions() {
      return this.columns.map(({ title, dataIndex, relations }) => {
        return {
          label: typeof title === "function" ? title() : title,
          value: dataIndex,
          relations: relations,
        }
      })
    },
    relationMap() {
      const relationMap = {}
      this.columns.map(({ dataIndex, relations }) => {
        const optionsfilters = relations ? relations.split(",") : ["eq"]
        relationMap[dataIndex] = relationBaseOptions.filter(({ value }) =>
          optionsfilters.includes(value)
        )
      })
      return relationMap
    },
    defCustomSearchData() {
      return this.columns.map(({ dataIndex }) => ({
        leftBracket1: false,
        leftBracket2: false,
        rightBracket1: false,
        rightBracket2: false,
        condition: "and",
        fieldName: dataIndex,
        relation: "",
        fieldValue: "",
      }))
    },
  },
  async beforeRouteEnter(to, from, next) {
    // 加载国际化
    await loadModuleMessage("workflow.model")
    next()
  },
  methods: {
    // 打开搜索面板并重置
    async open(element, form, flowConditions) {
      const that = this
      if (element) {
        that.element = element
      }
      this.setDefaultSet(flowConditions)
      if (this.workflowModel) {
        await this.getFlowConditionsList(this.workflowModel.categoryId)
      }
      this.visible = true
    },
    // 获取流程的流程条件集合
    getFlowConditionsList(cateId) {
      const that = this
      return new Promise(function (resolve, reject) {
        listFlowCondition(cateId)
          .then((response) => {
            // console.log('listFlowCondition', response.data)
            if (response) {
              that.columns = response.map((item) => {
                const list = {
                  title: item.name,
                  dataIndex: item.fieldName,
                  selectType: item.selectType,
                  key: item.id,
                }
                //  字符串 0 数字 1 字典 2
                if (item.selectType === "0") {
                  list.type = "varchar"
                  list.relations = "eq,neq"
                } else if (item.selectType === "1") {
                  list.type = "number"
                  list.relations = "eq,neq,gt,geq,lt,leq"
                } else if (item.selectType === "2") {
                  list.type = "dict"
                  list.dictGroup = item.dictGroup
                  list.relations = "eq"
                  try {
                    const data = []
                    const dicts = window.top.bt.dictContext[item.dictGroup]
                    for (var value in dicts) {
                      var key = dicts[value]
                      data.push({
                        value: value,
                        text: key.name,
                      })
                    }
                    item.dictGroupList = list.options = [...data]
                  } catch (e) {}

                  that.formItemConfigs[`${item.fieldName}_eq`] = () => {
                    const validSignSelect = getBaseSelectConfig({}) // 根据后台数据设置表单
                    validSignSelect.options.options = initDictOptions(
                      item.dictGroupList
                    )
                    return validSignSelect
                  }
                } else {
                  list.type = "varchar"
                  list.relations = "eq,neq"
                }
                return list
              })
            } else {
              that.columns = []
            }
            that.loading = false
            resolve(response.data)
          })
          .catch((error) => {
            that.loading = false
            reject(error)
          })
          .finally(() => {
            if (Array.isArray(that.columns) && that.columns.length) {
            } else {
              // that.$t("common.workflow.no.flowcondition")
              that.$message.warning("流程条件未配置")
            }
          })
      })
    },
    cancelPropertyConditions() {
      this.visible = false
      this.setDefaultSet()
    },
    // 重置
    setDefaultSet(flowConditions) {
      // 设置默认条件
      if (flowConditions?.length) {
        this.customSearchData = flowConditions.map(
          ({
            condition,
            fieldName,
            relation,
            fieldValue,
            leftBracket1,
            leftBracket2,
            rightBracket1,
            rightBracket2,
          }) => {
            return {
              leftBracket1: leftBracket1,
              leftBracket2: leftBracket2,
              rightBracket1: rightBracket1,
              rightBracket2: rightBracket2,
              condition: condition,
              fieldName: fieldName,
              relation: relation,
              fieldValue: fieldValue,
            }
          }
        )
      } else {
        this.customSearchData = [getBaseGroupValue()]
      }
      this.form.resetFields()
    },
    handleOk() {
      this.form.validateFields((err, values) => {
        if (!err) {
          if (!checkBrackets(this.customSearchData)) {
            this.$message.error(this.$t("workflow.model.error.logical.error"))
            return false
          }
          const that = this
          that.modalVisible = true
          that.customParamName = null
          const conditionsConfig = []
          let conditionalExpression = "${"
          values.group.map((item, i) => {
            const { leftBracket1, leftBracket2, rightBracket1, rightBracket2 } =
              that.customSearchData[i]
            that.columns.find((col) => {
              if (item.fieldName === col.dataIndex) {
                item.fieldLabel = col.title
                item.selectType = col.selectType
                item.relationLabel = conditionsMap.get(item.relation)
                if (col.type === "dict" && col.dictGroup) {
                  // item.fieldValueLabel = this.$dict(
                  //   col.dictGroup,
                  //   item.fieldValue
                  // )
                  const dicts = window.top.bt.dictContext[col.dictGroup]
                  for (var value in dicts) {
                      var key = dicts[value]
                      if(key.code === item.fieldValue) {
                        item.fieldValueLabel = key.name
                      }
                    }
                } else if (col.type === "number") {
                  if (typeof item.fieldValue === 'number') {
                    item.fieldValueLabel = parseFloat(item.fieldValue)
                  }else {
                    item.fieldValueLabel = item.fieldValue
                  }
                } else {
                  item.fieldValueLabel = item.fieldValue
                }
              }
            })
            item.leftBracket1 = leftBracket1
            item.leftBracket2 = leftBracket2
            item.rightBracket1 = rightBracket1
            item.rightBracket2 = rightBracket2
            leftBracket1 && (conditionalExpression += "(")
            leftBracket2 && (conditionalExpression += "(")
            conditionalExpression +=
              item.fieldName +
              "" +
              (item.relationLabel === "=" ? "==" : item.relationLabel)
            //  字符串 0 数字 1 字典 2
            if (item.selectType === "0") {
              conditionalExpression += '"' + item.fieldValue + '"'
            } else if (item.selectType === "1") {
              if (typeof item.fieldValue === 'number') {
                conditionalExpression += "" + parseFloat(item.fieldValue)
              }else {
                conditionalExpression += '"' + item.fieldValue + '"'
              }
            } else if (item.selectType === "2") {
              conditionalExpression += item.fieldValue
            } else {
              conditionalExpression += '"' + item.fieldValue + '"'
            }
            rightBracket1 && (conditionalExpression += ")")
            rightBracket2 && (conditionalExpression += ")")
            if (item.condition) {
              item.conditionLabel = conditionsMap.get(item.condition)
              conditionalExpression +=
                item.condition === "and" ? " && " : " || "
            }
            conditionsConfig.push(item)
          })
          conditionalExpression += "}"
          that.$emit("conditions", conditionsConfig, conditionalExpression)
          that.visible = false
          that.setDefaultSet()
        }
      })
    },
    // fieldName config
    getFieldNameConfig({ gIndex, defaultValue }) {
      return baseConfigs.getBaseSelectConfig({
        config: {
          label: "",
          rules: [{ required: true, message: " " }],
          model: `group[${gIndex}].fieldName`,
        },
        options: {
          options: this.fieldNameOptions,
          width: "100px",
          defaultValue,
        },
      })
    },
    // relation config
    getRelationConfig({ gIndex, defaultValue, group }) {
      return baseConfigs.getBaseSelectConfig({
        config: {
          label: "",
          rules: [{ required: true, message: " " }],
          model: `group[${gIndex}].relation`,
        },
        options: {
          width: "66px",
          options: this.relationMap[group.fieldName],
          defaultValue,
        },
      })
    },
    // condition config
    getConditionConfig({ gIndex, defaultValue }) {
      return baseConfigs.getBaseSelectConfig({
        config: {
          label: "",
          rules: [{ required: true, message: " " }],
          model: `group[${gIndex}].condition`,
        },
        options: { width: "66px", options: conditionOptions, defaultValue },
      })
    },
    // 获取表单渲染配置
    getFieldValueConfig({
      gIndex,
      defaultValue,
      group: { fieldName, fieldValue, relation, type },
    }) {
      const configKey = `${fieldName}_${relation}`
      let relationFieldValue = relation === "between" ? [] : null
      let baseConf = null
      const confInfo = this.formItemConfigs[configKey]

      // if (!confInfo) baseConf = baseConfigs.getBaseInputConfig(gIndex) // 未定义 则使用默认
      if (!confInfo) {
        baseConf = baseConfigs.getBaseInputConfig({})
      }

      if (Object.prototype.toString.call(confInfo) === "[object String]") {
        baseConf =
          baseConfigs[confInfo]?.({}) || baseConfigs.getBaseInputConfig({})
      }
      if (Object.prototype.toString.call(confInfo) === "[object Function]") {
        baseConf = confInfo()
      }
      if (Object.prototype.toString.call(confInfo) === "[object Object]") {
        baseConf = confInfo
      }
      if (defaultValue !== undefined) {
        relationFieldValue = defaultValue
      }
      Object.assign(baseConf.options, { defaultValue: relationFieldValue })
      Object.assign(baseConf, {
        label: "",
        model:
          relation === "between"
            ? `group[${gIndex}].fieldValues`
            : `group[${gIndex}].fieldValue`,
      })
      baseConf.rules = [{ required: true, message: " " }]

      return baseConf
    },
    // 新增一组
    addGroup() {
      this.customSearchData.push(getBaseGroupValue())
      // if (this.customSearchData?.length < this.columns?.length) {
      //     this.customSearchData.push(getBaseGroupValue())
      // }
    },
    delGroupItem(gIndex) {
      this.customSearchData.splice(gIndex, 1)
      this.form.resetFields()
    },
    fieldNameChange(gIndex) {
      this.customSearchData[gIndex].fieldValue = ""
      this.customSearchData[gIndex].relation = "eq"
      this.form.resetFields([`group[${gIndex}].relation`])
      this.form.resetFields([`group[${gIndex}].fieldValue`])
    },
    relationChange(gIndex) {
      this.customSearchData[gIndex].fieldValue = ""
      this.form.resetFields([`group[${gIndex}].fieldValue`])
    },
  },
}
</script>

<style lang="less" scoped>
.custom-design-form {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: flex-start;
  width: 100%;
  // margin-bottom: 16px;
  // border: 1px solid #e6e6e6;
  transition: all 0.3s;
  // &:hover {
  //     box-shadow: 0 2px 8px rgba(0, 0, 0, 0.09);
  // }

  .custom-search-group {
    .ant-form-item {
      margin-bottom: 0;

      .ant-form-explain,
      .ant-form-extra {
        display: none;
      }
    }

    .query-form-item.ant-form-item {
      width: auto;
    }

    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    // justify-content: space-around;
    // width: 358px;
    // background-color: #efefef;
    padding: 0 4px;
    // margin-bottom: 8px;

    .symbolbtn.ant-btn {
      padding: 0 8px;
      margin-top: 4px;
      border-radius: 0;

      &.right-symbol {
        // border-left: none;
      }
    }

    .ant-input,
    .ant-select-selection {
      // border-left: none;
      border-radius: 0;
    }

    .ant-btn.ant-btn-danger.ant-btn-circle {
      margin-top: 7px;
      margin-left: 8px;
    }
  }

  .group-condition {
    margin: 0 16px;
  }

  .addgroup-btn {
    margin-top: 12px;
    margin-left: -32px;
  }

  .btn-group {
    width: 100%;
    padding-top: 2px;
    text-align: center;

    .ant-btn:not(:first-child) {
      margin-left: 8px;
    }
  }
}
</style>
