import axios from "axios";
import notification from "ant-design-vue/es/notification";
import Modal from "ant-design-vue/es/modal";
// import { ACCESS_TOKEN } from "@/store/mutation-types";
import i18n, { i18nRender } from "@/locales";
import { message } from "ant-design-vue";
import Vue from "vue";

// create an axios instance
const service = axios.create({
  baseURL: process.env.VUE_APP_BASE_API, // url = base url + request url
  // withCredentials: true, // send cookies when cross-domain requests
  timeout: 100000, // request timeout
  validateStatus: function (status) {
    // `validateStatus` 定义对于给定的HTTP 响应状态码是 resolve 或 reject  promise 。
    // 如果 `validateStatus` 返回 `true` (或者设置为 `null` 或 `undefined`)，promise 将被 resolve; 否则，promise 将被 rejecte
    // return status >= 200 && status < 300; // 默认的
    return true;
  },
});
// 登录状态过期弹框引用，解决多个请求为401时，出现多个提示的问题
let modalObject = null;

// request interceptor
service.interceptors.request.use(
  (config) => {
    // do something before request is sent
    // const token = Vue.ls.get(ACCESS_TOKEN)

    const token =
      "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..csmT7ot2N83VRQdXXxaCDNolY3gxpf3JLVhqj9fKRA0.csmT7ot2N83VRQdXXxaCDNolY3gxpf3JLVhqj9fKRA0";
    // if (store.getters.token) {
    if (token) {
      // let each request carry token
      // ['X-Token'] is a custom headers key
      // please modify it according to the actual situation
      // config.headers['Authorization'] = 'Bearer ' + getToken()
      //config.headers["Authorization"] = "Bearer " + token;
      config.headers["Accept-Language"] = i18n.locale;
    } else {
      config.headers["Accept-Language"] = "zh-CN,zh;q=0.9";
    }

    if (config.method === "get") {
      config.params = {
        _t: Date.parse(new Date()) / 1000,
        ...config.params,
      };
    }
    // config.baseURL = '/local'
    // if (config.url.includes('/demo'))config.baseURL = '/local'
    return config;
  },
  (error) => {
    // do something with request error
    console.log(error); // for debug
    return Promise.reject(error);
  }
);

// response interceptor
service.interceptors.response.use(
  /**
   * If you want to get http information such as headers or status
   * Please return  response => response
   */

  /**
   * Determine the request status by custom code
   * Here is just an example
   * You can also judge the status by HTTP Status Code
   */
  (response) => {
    const res = response.data;
    // response.status = window.status ? Number(window.status) : response.status
    if (response.status !== 200) {
      if (
        response.status === 401 &&
        (window.location.pathname !== "/user/login" ||
          window.location.pathname !== "/user/adminLogin") &&
        window.location.pathname !== "/"
      ) {
        if (modalObject) {
          modalObject.destroy();
        }
        // modalObject = Modal.confirm({
        //   cancelButtonProps: {
        //     disabled: true,
        //   },
        //   class: "overdueLoginReminder",
        //   keyboard: false,
        //   cancelText: null,
        //   title: "系统提示",
        //   content: "登录状态已过期，请重新登录",
        //   onOk: () => {
        //     return store.dispatch("Logout2").then(() => {
        //       if (
        //         window.location.pathname !== "/user/login" ||
        //         window.location.pathname !== "/user/adminLogin"
        //       ) {
        //         const type = store.getters.userType;
        //         store.commit("SET_USER_TYPE", "");
        //         if (type === "admin") {
        //           location.href = "/user/adminLogin";
        //         } else {
        //           location.href = "/user/login";
        //         }
        //       }
        //     });
        //   },
        // });
      } else if (res.code === "CM4001") {
        // 错误码显示格式：系统错误码【CM50000】，请联系管理员
        // message.error(i18nRender(res.msg))
        message.error("系统错误码【" + res.code + "】，" + i18nRender(res.msg));
      } else if (response.status === 503) {
        return Promise.reject(
          new Error(
            "系统错误码【CM5003】，" + i18nRender("service.unavailable")
          )
        );
      } else if (!res.code || response.status === 502) {
        return Promise.reject(
          new Error("系统错误码【CM5002】，网关服务异常，请稍后重试")
        );
      }
      // return Promise.reject(new Error(i18nRender(res.msg) + '，错误码：[' + res.code + ']' || 'Error'))
      return Promise.reject(
        new Error(
          "系统错误码【" + res.code + "】，" + i18nRender(res.msg) || "Error"
        )
      );
    } else {
      // 错误码显示格式：系统错误码【CM50000】，请联系管理员
      if (res.code === "CM4001") {
        message.error("系统错误码【" + res.code + "】，" + i18nRender(res.msg));
      }
      // else if (res.code && res.code !== 'CM2000') {
      //     message.error(i18nRender(res.msg) + '，错误码：[' + res.code + ']')
      // }
      // 后端设置了Content-Disposition, 则拼接Content-Disposition到data中
      if (
        response.headers["access-control-expose-headers"] ===
        "Content-Disposition"
      ) {
        res._contentDisposition = response.headers["content-disposition"];
      }
      return res;
    }
  },
  (error) => {
    let { message } = error;
    if (message === "Network Error") {
      // message = "后端接口连接异常";
      message = "系统服务器连接异常，请稍后再试";
    } else if (message.includes("timeout")) {
      message = "系统接口请求超时";
    } else if (message.includes("Request failed with status code")) {
      message = "系统接口" + message.substr(message.length - 3) + "异常";
    }
    notification.error({
      message: message,
      type: "error",
      duration: 5 * 1000,
    });
    return Promise.reject(error);
  }
);

export default service;
