<template>
  <div class="containers" ref="content">
    <div>
      <a-divider orientation="left">
        {{ title }}
      </a-divider>
    </div>
    <div style="margin-left: 20px">
      <a-button @click="saveModelInfo">
        <!-- 保存-->
        {{ $t("common.btn.save") }}
      </a-button>

      <a-button-group>
        <a-button @click="handlerUndo">
          <!--            撤销-->
          {{ $t("common.btn.cancel") }}
        </a-button>
        <a-button @click="handlerRedo">
          <!--          恢复-->
          {{ $t("common.btn.recovery") }}
        </a-button>
      </a-button-group>

      <a-button-group>
        <a-button @click="handlerZoom(0.1)">
          <!--          放大-->
          {{ $t("workflow.model.btn.zoom") }}
        </a-button>
        <a-button @click="handlerZoom(-0.1)">
          <!--          缩小-->
          {{ $t("workflow.model.btn.zoomOut") }}
        </a-button>
        <a-button @click="handlerZoom(0)">
          <!--            还原-->
          {{ $t("workflow.model.btn.restore") }}
        </a-button>
      </a-button-group>

      <a hidden ref="downloadLink"></a>
    </div>

    <div class="canvas" ref="canvas"></div>
    <div id="js-properties-panel" class="panel"></div>
    <CustomPropertyPanel
      v-if="bpmnModeler"
      ref="propertyPanel"
      :workflowModel="workflowModel"
      :modeler="bpmnModeler"
    />
  </div>
</template>

<script>
import BpmnModeler from "bpmn-js/lib/Modeler"

import CustomPropertyPanel from "@/views/flowDesigner/customPropertyPanel/CustomPropertyPanel.vue"
import propertiesProviderModule from "bpmn-js-properties-panel/lib/provider/camunda"
import camundaModdleDescriptor from "camunda-bpmn-moddle/resources/camunda.json"
import customModule from "./custom/index"

// BPMN国际化
import customTranslate from "@/bpmnJs/customTranslate/customTranslate"
import { emptyModelXml } from "@/bpmnJs/emptyModelXml"
import { getModel, updateModel } from "@/api/workflow/model"

// 自定义汉化模块
var customTranslateModule = {
  translate: ["value", customTranslate],
}
export default {
  name: "CamundaWorkflowDesigner",
  components: { CustomPropertyPanel },
  data() {
    return {
      title: null,
      bpmnModeler: null,
      container: null,
      canvas: null,
      scale: 1,
      workflowModel: {
        modelName: null,
        modelId: null,
        corpId: null,
        proDefKey: null,
        corpName: null,
        modelData: null,
      },
      modelId: this.$route.query.modelId,
    }
  },
  created() {},
  async beforeCreate() {},
  async mounted() {
    const modelId = this.modelId
    if (!modelId) {
      this.$store.commit("SET_REMOVE_KEY", this.$route.fullPath)
      return
    }
    // 获取流程模型信息
    await this.getModelInfo(modelId)
    if (this.workflowModel) {
      if (this.workflowModel.modelName) {
        this.title =
          this.workflowModel.modelName +
          "  （" +
          this.workflowModel.corpName +
          "）"
      }
    }
    // 初始化流程设计器对象
    await this.initBpmnModeler()
    // 获取流程模型的XML数据
    const modelXml = this.getWorkFlowCategoryModelXml()
    // 初始化流程模型
    await this.createNewDiagram(modelXml)
  },
  methods: {
    /**
     * 初始化流程设计器对象
     * @returns {Promise<void>}
     */
    async initBpmnModeler() {
      // 获取到属性ref为“content”的dom节点
      this.container = this.$refs.content
      // 获取到属性ref为“canvas”的dom节点
      const canvas = this.$refs.canvas
      // 创建BpmnModeler
      this.bpmnModeler = new BpmnModeler({
        container: canvas,
        // 加入工具栏支持
        propertiesPanel: {
          parent: "#js-properties-panel",
        },
        additionalModules: [
          // 左边工具栏以及节点
          propertiesProviderModule,
          // 自定义Palette / contextPad
          customModule,
          // 右边的工具栏
          // propertiesPanelModule,
          // 国际化
          customTranslateModule,
        ],
        moddleExtensions: {
          camunda: camundaModdleDescriptor,
        },
      })
    },
    getDecode(str) {
      return decodeURIComponent(
        atob(str)
          .split("")
          .map(function (c) {
            return "%" + ("00" + c.charCodeAt(0).toString(16)).slice(-2)
          })
          .join("")
      )
    },
    // 获取流程模型的XML数据
    getWorkFlowCategoryModelXml() {
      let modelXml = ""
      if (this.workflowModel) {
        const modelData = this.workflowModel.modelData
        if (modelData) {
          // base64解码
          modelXml = this.getDecode(modelData)
          console.log(modelXml)
        } else {
          modelXml = this.getEmptyModelXml()
        }
      } else {
        modelXml = emptyModelXml
      }
      return modelXml
    },
    getEmptyModelXml() {
      let id = "Process_1"
      let name = "新建流程模型名称"
      if (this.workflowModel) {
        id = this.workflowModel.proDefKey
        name = this.workflowModel.name
      }
      return `<?xml version="1.0" encoding="UTF-8"?>
                <bpmn2:definitions xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:bpmn2="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xsi:schemaLocation="http://www.omg.org/spec/BPMN/20100524/MODEL BPMN20.xsd" id="sample-diagram" targetNamespace="http://bpmn.io/schema/bpmn">
                  <bpmn2:process id="${id}" name="${name}" isExecutable="true">
                    <bpmn2:startEvent id="StartEvent_1"/>
                  </bpmn2:process>
                  <bpmndi:BPMNDiagram id="BPMNDiagram_1">
                    <bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="Process_1">
                      <bpmndi:BPMNShape id="_BPMNShape_StartEvent_2" bpmnElement="StartEvent_1">
                        <dc:Bounds height="36.0" width="36.0" x="412.0" y="240.0"/>
                      </bpmndi:BPMNShape>
                    </bpmndi:BPMNPlane>
                  </bpmndi:BPMNDiagram>
                </bpmn2:definitions>`
    },
    /**
     * 创建新流程
     * @param bpmn BPMN流程XML报文
     * @returns {Promise<void>}
     */
    async createNewDiagram(bpmn) {
      // 将字符串转换成图显示出来;
      try {
        const result = this.bpmnModeler.importXML(bpmn)
        const { warnings } = result
        if (warnings) {
          console.log(warnings)
        }
      } catch (err) {
        this.$message.error("打开模型出错,请确认该模型符合Bpmn2.0规范")
        console.log(err.message, err.warnings)
      }
      // this.bpmnModeler.importXML(bpmn, err => {
      //     if (err) {
      //         console.error(err)
      //         this.$message.error('打开模型出错,请确认该模型符合Bpmn2.0规范')
      //     } else {
      //         // console.log('成功导入模型')
      //     }
      // })
    },
    // 获取模型信息
    async getModelInfo(id) {
      const that = this
      return new Promise(function (resolve, reject) {
        getModel(id)
          .then((response) => {
            if (response.success) {
              if (response.obj) {
                that.workflowModel = response.obj
              }
            }
            that.loading = false
            resolve(response.obj)
          })
          .catch((error) => {
            that.loading = false
            reject(error)
          })
      })
    },

    // 字符串转base64
    getEncode64(str) {
      return btoa(
        encodeURIComponent(str).replace(
          /%([0-9A-F]{2})/g,
          function toSolidBytes(match, p1) {
            return String.fromCharCode("0x" + p1)
          }
        )
      )
    },
    // 保存流程模型
    saveModelInfo() {
      const _this = this
      this.$refs.propertyPanel.$refs.refForm.validate((valid) => {
        if (valid) {

          const modelId = _this.workflowModel?.id
          const data = Object.assign({}, _this.workflowModel)

          this.$confirm({
            title: _this.$t("common.title.info"),
            content: _this.$t("common.confirm.save"),
            async onOk() {
              // 获取流程模型的XML数据
              const xmlData = await _this.getModelXml()
              if (xmlData) {
                // 使用base64编码，解决XML报文会被转义的问题
                data.modelData = _this.getEncode64(xmlData)
              }
              const request = updateModel(data)
              return request.then((response) => {
                if (response.success) {
                  _this.$confirm({
                    title: _this.$t("common.title.info"),
                    content: "保存成功！是否关闭当前页面？",
                    async onOk() {
                      // 关闭当前页面
                      _this.$store.commit(
                        "SET_REMOVE_KEY",
                        _this.$route.fullPath
                      )
                      setTimeout(() => {
                        window.top.bt && window.top.bt.navtab.closeCurrent()
                      }, 50)
                    },
                    async onCancel() {
                      // 重新加载流程模型
                      if (modelId) {
                        // 获取流程模型信息
                        await _this.getModelInfo(_this.workflowModel.id)
                        // 获取流程模型的XML数据
                        const modelXml = _this.getWorkFlowCategoryModelXml()
                        // 初始化流程模型
                        await _this.createNewDiagram(modelXml)
                      }
                    },
                  })
                } else {
                  _this.$error({ title: response.msg})
                }
              })
            },
          })
        }
      })
    },
    // 获取流程模型的XML数据
    async getModelXml() {
      const that = this
      return new Promise(function (resolve, reject) {
        that.bpmnModeler.saveXML({ format: true }, (err, xml) => {
          if (!err) {
            resolve(xml)
          } else {
            reject(err)
          }
        })
      })
    },
    handlerRedo() {
      this.bpmnModeler.get("commandStack").redo()
    },
    handlerUndo() {
      this.bpmnModeler.get("commandStack").undo()
    },
    handlerZoom(radio) {
      const newScale = !radio ? 1.0 : this.scale + radio
      this.bpmnModeler.get("canvas").zoom(newScale)
      this.scale = newScale
    },
    beforeUpload(file) {
      this.openBpmn(file)
      return false
    },
    openBpmn(file) {
      const reader = new FileReader()
      // 读取File对象中的文本信息，编码格式为UTF-8
      reader.readAsText(file, "utf-8")
      reader.onload = () => {
        // 读取完毕后将文本信息导入到Bpmn建模器
        this.createNewDiagram(reader.result)
      }
      return false
    },
    // 下载bpmn
    downloadBpmn() {
      this.bpmnModeler.saveXML({ format: true }, (err, xml) => {
        if (!err) {
          // 获取文件名
          const name = `camunda-${this.getFilename(xml)}.bpmn`
          // 将文件名以及数据交给下载方法
          this.download({ name: name, data: xml })
        }
      })
    },
    downloadSvg() {
      this.bpmnModeler.saveXML({ format: true }, (err, xml) => {
        if (!err) {
          // 获取文件名
          const name = `camunda-${this.getFilename(xml)}.svg`

          // 从建模器画布中提取svg图形标签
          let context = ""
          const djsGroupAll = this.$refs.canvas.querySelectorAll(".djs-group")
          for (const item of djsGroupAll) {
            context += item.innerHTML
          }
          // 获取svg的基本数据，长宽高
          const viewport = this.$refs.canvas
            .querySelector(".viewport")
            .getBBox()

          // 将标签和数据拼接成一个完整正常的svg图形
          const svg = `
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          xmlns:xlink="http://www.w3.org/1999/xlink"
                          width="${viewport.width}"
                          height="${viewport.height}"
                          viewBox="${viewport.x} ${viewport.y} ${viewport.width} ${viewport.height}"
                          version="1.1"
                          >
                          ${context}
                        </svg>
                      `
          // 将文件名以及数据交给下载方法
          this.download({ name: name, data: svg })
        }
      })
    },
    // 下载bpmn文件
    download({ name = "diagram.bpmn", data }) {
      // 这里就获取到了之前设置的隐藏链接
      const downloadLink = this.$refs.downloadLink
      // 把输就转换为URI，下载要用到的
      const encodedData = encodeURIComponent(data)

      if (data) {
        // 将数据给到链接
        downloadLink.href =
          "data:application/bpmn20-xml;charset=UTF-8," + encodedData
        // 设置文件名
        downloadLink.download = name
        // 触发点击事件开始下载
        downloadLink.click()
      }
    },
    // 生成文件名称
    getFilename(xml) {
      const start = xml.indexOf("process")
      let filename = xml.substr(start, xml.indexOf(">"))
      filename = filename.substr(filename.indexOf("id") + 4)
      filename = filename.substr(0, filename.indexOf('"'))
      return filename
    },
  },
  computed: {},
}
</script>

<style lang="less" scoped>
// 左边工具栏以及编辑节点的样式
@import "~bpmn-js/dist/assets/diagram-js.css";
@import "~bpmn-js/dist/assets/bpmn-font/css/bpmn.css";
@import "~bpmn-js/dist/assets/bpmn-font/css/bpmn-codes.css";
@import "~bpmn-js/dist/assets/bpmn-font/css/bpmn-embedded.css";

// 右边工具栏样式
@import "~bpmn-js-properties-panel/dist/assets/bpmn-js-properties-panel.css";

.containers {
  position: absolute;
  background-color: #ffffff;
  width: calc(100% - 20px);
  height: calc(100vh - 50px);
  padding: 5px;
}
.canvas/deep/ .bjs-powered-by {
  visibility: hidden;
}
.canvas {
  width: 100%;
  height: calc(100% - 120px);
}

.panel {
  position: absolute;
  right: 0;
  top: 0;
  width: 300px;
}
.canvas/deep/ .bpmn-icon-lasso-tool,
.canvas/deep/ .bpmn-icon-space-tool,
.canvas/deep/ .bpmn-icon-data-store,
.canvas/deep/ .bpmn-icon-subprocess-expanded,
.canvas/deep/ .bpmn-icon-data-object,
.canvas/deep/ .bpmn-icon-group,
.canvas/deep/ .bpmn-icon-participant,
.canvas/deep/ .bpmn-icon-intermediate-event-none,
.canvas/deep/ .bpmn-icon-text-annotation,
.canvas/deep/ .djs-popup-body div,
.canvas/deep/ .bpmn-icon-task,
.canvas/deep/ .djs-context-pad .bpmn-icon-screw-wrench {
  display: none !important;
}

.canvas/deep/ .djs-popup-body .bpmn-icon-user {
  display: block !important;
}
/*更改图标形状*/
.canvas/deep/ .bpmn-icon-gateway-none:before {
  content: "\e80f";
} /* '' */

.canvas/deep/ .djs-palette.two-column.open {
  width: 48px;
}
</style>
