import request from '@/utils/request'


// 根据用户ID获取用户列表
export function listUserByIds (ids) {
  return request({
    url: '/sys/user/listByIds',
    method: 'post',
    data: ids
  })
}


// 根据角色ID获取用户列表
export function getWorkFlowUserByRoleIds (data) {
    return request({
        url: '/sys/user/listByRoleIdsV2',
        method: 'post',
        data: data
    })
}

// 获取拥有指定单位、用户ID集合
export function getHasPermissionUserIds (corpId, permission) {
  return request({
    url: '/sys/user/listApproveUserByCorpId?corpId=' + corpId,
    method: 'get'
  })
}





