<template>
  <a-modal
    v-drag-modal
    v-model="candidateModalVisible"
    style="z-index: 99"
    :width="1024"
    :title="$t('workflow.model.title.approval.configuration')"
    :maskClosable="false"
    :destroyOnClose="true"
    :keyboard="false"
    :ok-text="$t('common.btn.confirm')"
    :cancel-text="$t('common.btn.cancel')"
    :afterClose="afterCandidateModalClose"
    @ok="handleOk"
    :bodyStyle="{ padding: '0px 15px 5px 15px', overflow: 'auto' }"
  >
    <div style="height: 616px">
      <a-tabs :activeKey="candidateType" @change="handleCandidateTypeChange">
        <a-tab-pane
          style="height: 450px"
          key="user"
          :tab="this.userTab"
          force-render
        >
          <a-row style="height: 100%">
            <a-col
              :span="8"
              style="
                height: 100%;
                padding-right: 10px;
                border-right: 1px dashed #b9b9b9;
              "
            >
              <h3>{{ $t("workflow.model.title.member.units") }}</h3>
              <!--            <a-input-search-->
              <!--              style="margin-bottom: 8px"-->
              <!--              placeholder="Search"-->
              <!--              @change="onCorpSearchValueChange"/>-->
              <a-spin :spinning="corpTreeLoading">
                <div
                  style="height: 400px; overflow: auto; border: 1px solid #eee"
                >
                  <a-tree
                    :expanded-keys="expandedCorpKeys"
                    :auto-expand-parent="corpAutoExpandParent"
                    :tree-data="corpTreeList"
                    :replaceFields="{
                      title: 'name',
                      key: 'id',
                      children: 'children',
                    }"
                    :showLine="false"
                    :selectedKeys="currentCorpKeys"
                    @expand="onCorpExpand"
                    @select="onCorpNodeClick"
                  >
                    <template slot="title" slot-scope="{ title }">
                      <span v-if="title.indexOf(searchCorpValue) > -1">
                        {{ title.substr(0, title.indexOf(searchCorpValue)) }}
                        <span style="color: #f50">{{ searchCorpValue }}</span>
                        {{
                          title.substr(
                            title.indexOf(searchCorpValue) +
                              searchCorpValue.length
                          )
                        }}
                      </span>
                      <span v-else>{{ title }}</span>
                    </template>
                  </a-tree>
                </div>
              </a-spin>
            </a-col>
            <a-col
              :span="8"
              style="
                height: 100%;
                padding-left: 10px;
                padding-right: 10px;
                border-right: 1px dashed #b9b9b9;
              "
            >
              <h3>{{ $t("workflow.model.title.alternative.users") }}</h3>
              <a-spin :spinning="corpUsersLoading">
                <div
                  style="
                    height: 400px;
                    overflow: scroll;
                    border: 1px solid #eeeeee;
                  "
                >
                  <template v-if="currentCorpKeys != null">
                    <a-list
                      v-show="currentCorpUsers.length > 0"
                      size="small"
                      bordered
                    >
                      <template v-for="(user, index) in currentCorpUsers">
                        <a-list-item
                          :key="index"
                          style="cursor: pointer"
                          :class="getSelectUserClassObject(user)"
                          @click="onAlternativeUserItemClick(user)"
                        >
                          <div>
                            <h4>({{ user.loginName }}){{ user.username }}</h4>
                            <h5>{{ user.corpName }}</h5>
                          </div>
                        </a-list-item>
                      </template>
                    </a-list>

                    <empty
                      v-show="
                        currentCorpUsers.length === 0 &&
                        corpUsersLoading === false
                      "
                    >
                      <span slot="description">{{
                        $t("workflow.model.message.not.user")
                      }}</span>
                    </empty>
                  </template>
                  <template v-else>
                    <empty>
                      <span slot="description">{{
                        $t("workflow.model.message.choice.corp")
                      }}</span>
                    </empty>
                  </template>
                </div>
              </a-spin>
            </a-col>
            <a-col
              :span="8"
              style="height: 100%; padding-left: 10px; padding-right: 10px"
            >
              <h3>{{ $t("workflow.model.message.selected.users") }}</h3>
              <a-spin :spinning="candidateUsersLoading">
                <div
                  style="
                    height: 400px;
                    overflow: scroll;
                    border: 1px solid #eee;
                  "
                >
                  <a-list
                    v-show="candidateUsers.length > 0"
                    size="small"
                    bordered
                  >
                    <template v-for="(user, index) in candidateUsers">
                      <a-list-item
                        :key="index"
                        style="cursor: pointer"
                        @click="removeCandidateUser(user)"
                      >
                        <div>
                          <h4>({{ user.loginName }}){{ user.username }}</h4>
                          <h5>{{ user.corpName }}</h5>
                        </div>
                      </a-list-item>
                    </template>
                  </a-list>
                </div>
              </a-spin>
            </a-col>
          </a-row>
        </a-tab-pane>

        <a-tab-pane
          key="role"
          :tab="this.roleUserTab"
          style="height: 450px; overflow: auto"
        >
          <template v-if="roles.length > 0">
            <a-list
              :grid="{ gutter: 16, xs: 1, sm: 2, md: 4, lg: 4, xl: 6, xxl: 4 }"
              :data-source="roles"
            >
              <template v-for="(role, index) in roles">
                <a-list-item
                  :key="index"
                  style="cursor: pointer; margin-right: 15px; width: 300px"
                >
                  <a-card :class="getSelectRoleClassObject(role)" size="small">
                    <div style="float: left">
                      <span> {{ role.name }}</span>
                    </div>
                    <div style="width: 80px; float: right">
                      <span
                        style="text-align: center; display: block; float: right"
                      >
                        <a-icon
                          style="margin-top: 5px"
                          :type="
                            getSelectRoleObject(role)
                              ? 'close-circle'
                              : 'plus-circle'
                          "
                          class="operate icon"
                          @click.stop="onRoleItemClick(role)"
                        />
                      </span>
                      <span
                        style="text-align: center; display: block; float: right"
                        class="operate"
                        @click.stop="review(role)"
                        ><a-icon type="eye"
                      /></span>
                    </div>
                  </a-card>
                </a-list-item>
              </template>
            </a-list>
          </template>
          <template v-else>
            <empty>
              <span slot="description">{{
                $t("workflow.model.message.not.role")
              }}</span>
            </empty>
          </template>
        </a-tab-pane>
      </a-tabs>
      <br />
      <a-row>
        <h3>
          {{ $t("workflow.model.message.chose.approval") }}
          <span v-if="candidateUsersCount > 0"
            >（{{ passNumber ? passNumber : 0 }}/{{
              candidateUsersCount
            }}）</span
          >
        </h3>
        <a-col :span="20">
          <a-slider
            v-if="candidateUsersCount !== undefined"
            v-model="passNumber"
            :min="0"
            :max="candidateUsersCount"
          />
        </a-col>
        <a-col :span="2">
          <a-input-number
            :tooltip-visible="true"
            :value="passNumber"
            :min="0"
            :max="candidateUsersCount"
            style="margin-left: 15px"
            @change="changePassNumber"
          />
        </a-col>
      </a-row>
    </div>
    <role-user-detail ref="RoleUserDetail" />
  </a-modal>
</template>

<script>
import { Empty } from "ant-design-vue"

import { getCorpComponentTreeData } from "@/api/system/corp/corp"
import {
  listUserByIds,
  getHasPermissionUserIds,
  getWorkFlowUserByRoleIds,
} from "@/api/system/user/user"
import { getAllRole } from "@/api/system/role/role"
import RoleUserDetail from "@/views/flowDesigner/customPropertyPanel/RoleUserDetail"

const getCorpParentId = (corpId, tree) => {
  let parentKey
  for (let i = 0; i < tree.length; i++) {
    const node = tree[i]
    if (node.children) {
      if (node.children.some((item) => item.parentId === corpId)) {
        parentKey = node.id
      } else if (getCorpParentId(corpId, node.children)) {
        parentKey = getCorpParentId(corpId, node.children)
      }
    }
  }
  return parentKey
}

const initCorpTreeList = function (tree) {
  if (!tree) {
    return []
  }
  for (let i = 0; i < tree.length; i++) {
    const node = tree[i]
    if (node.children && node.children.length) {
      initCorpTreeList(node.children)
    }
    node.name = node.code ? `(${node.code}) ${node.name}` : node.name
  }
}
export default {
  name: "ConfigCandidateModal",
  components: {
    Empty,
    RoleUserDetail,
  },
  created() {},
  data() {
    return {
      workflowModel: null,
      element: null,
      form: {
        id: "",
        name: "",
        color: null,
      },
      queryParam: {
        roleIds: [],
        corpId: "",
      },
      loading: false,
      userTab: "",
      roleUserTab: "",
      // 弹出框是否可见
      candidateModalVisible: false,
      // 记录有该流程有审批权限的用户ID集合
      hasPermissionUserIds: new Set(),
      hasPermissionUsers:new Set(),
      // 记录已经选中的角色
      candidateGroups: [],
      // 记录已经选中的角色ID
      candidateGroupsIdSet: new Set(),
      // 记录已经选中的角色对应的用户Id
      candidateGroupUserIdSet: new Set(),
      // 记录已经选中的用户ID
      candidateUsersIdSet: new Set(),
      candidateUsers: [],
      candidateUsersLoading: false,
      // 已经选中的审批人员数量
      candidateUsersCount: undefined,
      candidateType: "user",

      // 角色列表
      roles: [],
      // 最少审批人数
      passNumber: 1,

      currentCorpKeys: null,
      currentCorpUsers: [],
      corpUsersLoading: false,
      expandedCorpKeys: [],
      searchCorpValue: "",
      // 成员单位列表
      corpTreeList: [],
      corpAutoExpandParent: true,
      corpTreeLoading: false,
    }
  },
  mounted() {},
  computed: {},
  async beforeRouteEnter(to, from, next) {
    next()
  },
  methods: {
    // 当改变审批人数时，passNumber 为非数字时，改成0，否则slide组件是抛出错误
    changePassNumber(value) {
      if (typeof value === "number") {
        this.passNumber = value
      } else {
        this.passNumber = 0
      }
    },
    review(role) {
      role.corpId = this.workflowModel.corpId
      this.$refs.RoleUserDetail.showModal(role)
    },
    /**
     * 展示【审批人员配置】modal
     */
    async showModal(workflowModel, element, form) {
      const that = this
      that.candidateModalVisible = true
      that.loading = true
      if (!workflowModel) {
        that.loading = false
        that.candidateModalVisible = false
        this.$message.warning(that.$t("workflow.model.error.data"))
        return
      }
      console.log("workflowModel ====" + workflowModel)
      that.workflowModel = workflowModel
      that.resetData()
      if (element) {
        that.element = element
      }
      that.getCorpList()
      that.getElementPassNumber()
      that.getRoleList()

      // 获取拥有指定单位【流程审批】权限的用户ID集合
      await that.getHasPermissionUserIds()

      if (form) {
        if (form["candidateGroups"]) {
          that.candidateGroups = form["candidateGroups"].split(",") || []
          that.candidateGroups.forEach((item, index, arr) => {
            that.candidateGroupsIdSet.add(item)
          })
        }
        if (form["candidateUsers"]) {
          const candidateUsersIds = form["candidateUsers"].split(",") || []
          // 获取【已选用户】的信息
          that.getCandidateUsersInfo(candidateUsersIds)
          candidateUsersIds.forEach((item, index, arr) => {
            that.candidateUsersIdSet.add(item)
          })
          // 已选择的审批人数
        }
        that.listUserByRoleIds()
        that.form = form
      }
      that.loading = false
    },
    closeModal() {
      this.candidateModalVisible = true
    },

    getSelectUserClassObject: function (user) {
      let isSelected = false
      if (user) {
        isSelected = this.candidateUsersIdSet.has(user.id)
      }
      return {
        "list-select-user-active": isSelected,
      }
    },
    getSelectRoleClassObject: function (role) {
      let isSelected = false
      if (role) {
        isSelected = this.candidateGroupsIdSet.has(role.id)
      }
      return {
        "list-select-user-active": isSelected,
      }
    },
    getSelectRoleObject: function (role) {
      let isSelected = false
      if (role) {
        isSelected = this.candidateGroupsIdSet.has(role.id)
      }
      return isSelected
    },
    // 获取拥有指定单位【流程审批】权限的用户ID集合
    async getHasPermissionUserIds() {
      const that = this
      const corpId = that.workflowModel.corpId
      return new Promise(function (resolve, reject) {
        getHasPermissionUserIds(corpId, "workflow:todoProcess:approve")
          .then((res) => {
            if (res) {
              console.log(res)
              that.hasPermissionUsers.clear()
              that.hasPermissionUserIds.clear()
              res.forEach((item, index, arr) => {
                that.hasPermissionUserIds.add(item.id)
                that.hasPermissionUsers.add(item)
              })
            }
            resolve(res)
          })
          .catch((error) => {
            reject(error)
          })
      })
    },
    /**
     * 获取用户信息
     */
    getCandidateUsersInfo(userIds) {
      if (userIds.length === 0) {
        return
      }
      const that = this
      that.candidateUsersLoading = true
      listUserByIds(userIds)
        .then((res) => {
          if (res) {
            const data = res
            data.forEach((item, index, arr) => {
              // 标识该用户已被选中
              item.isSelected = true
            })
            that.candidateUsers = data
          }
          that.candidateUsersLoading = false
        })
        .catch((error) => {
          console.error(error)
          that.candidateUsersLoading = false
        })
    },
    /**
     * 查询租户所有角色
     */
    getRoleList() {
      const that = this
      getAllRole()
        .then((response) => {
          that.roles = response
        })
        .catch((error) => {
          console.log("error", error)
        })
    },
    /**
     * 获取成员单位列表
     */
    getCorpList() {
      const that = this
      that.corpTreeLoading = true
      const queryParams = {
        resource: "workflow:todoProcess:approve",
      }
      getCorpComponentTreeData(queryParams)
        .then((response) => {
          that.corpTreeLoading = false
          if (response) {
            initCorpTreeList(response)
            that.corpTreeList = response
          }
        })
        .catch((error) => {
          console.log("error", error)
          that.corpTreeLoading = false
        })
    },
    /**
     * 获取成员单位-用户列表
     */
    getCorpUserList(selectedKeys) {
      const that = this
      if (that.corpUsersLoading === true) {
        this.$message.warning(that.$t("workflow.model.message.data.reload"))
        return
      }
      that.corpUsersLoading = true
      that.currentCorpUsers = []
      console.log(selectedKeys)
      that.corpUsersLoading = false
      // 根据有审批权限的用户ID过滤用户，没有审批权限就不展示了
      that.hasPermissionUsers.forEach(user=>{
        console.log(user)
        if (!that.candidateUsersIdSet.has(user.id)&&selectedKeys[0]===user.corpId) {
          that.currentCorpUsers.push(user)
        }
      })
/*      getHasPermissionUserIds(selectedKeys)
        .then((res) => {
          that.corpUsersLoading = false
          if (res) {
            // 根据有审批权限的用户ID过滤用户，没有审批权限就不展示了
            const currentCorpUsers = []
            res.forEach((user, index, arr) => {
              console.log(that.hasPermissionUserIds)
              if (!that.candidateUsersIdSet.has(user.id)) {
                currentCorpUsers.push(user)
              }
            })
            that.currentCorpUsers = currentCorpUsers
          } else {
            console.log("no user")
            that.currentCorpUsers = []
          }
        })
        .catch((error) => {
          console.error(error)
          that.corpUsersLoading = false
        })*/
    },
    // 获取最少审批人数配置
    getElementPassNumber() {
      const that = this
      const element = that.element
      if (!element) {
        return
      }
      const businessObject = element.businessObject
      if (!businessObject.extensionElements) {
        return
      }
      const extensionElementValues = businessObject.extensionElements.values
      extensionElementValues &&
        extensionElementValues.forEach((extensionElementValue, index, arr) => {
          if (extensionElementValue.$type === "camunda:Properties") {
            const propertiesValues = extensionElementValue.values
            if (propertiesValues) {
              for (let i = 0, size = propertiesValues.length; i < size; i++) {
                if (
                  propertiesValues[i].$type === "camunda:Property" &&
                  propertiesValues[i].name === "passNumber"
                ) {
                  // 最少审批人数配置
                  that.passNumber = parseInt(propertiesValues[i].value)
                  break
                }
              }
            }
          }
        })
    },
    /**
     * Modal关闭事件
     */
    afterCandidateModalClose() {
      this.resetData()
    },
    /**
     * 【按用户】和【按角色】切换事件
     */
    handleCandidateTypeChange(key) {
      this.candidateType = key
    },
    /**
     * 审批人员配置 - 确认事件
     */
    handleOk() {
      if (!this.passNumber) {
        this.$message.error(this.$t("workflow.model.error.add.apeople"))
        return
      }
      const candidateUsersIds = []
      this.candidateUsers.forEach((user, index, arr) => {
        candidateUsersIds.push(user.id)
      })
      const candidateGroupsIds = []
      this.candidateGroupsIdSet.forEach((crop, index, arr) => {
        candidateGroupsIds.push(crop)
      })
      // 回调父组件事件
      this.$emit("ok", {
        candidateGroups: candidateGroupsIds,
        candidateUsersIds: candidateUsersIds,
        candidateUsersCount: this.candidateUsersCount,
        passNumber: this.passNumber,
      })
      this.candidateModalVisible = false
      this.resetData()
    },
    /**
     * 查询角色下员工信息
     */
    listUserByRoleIds() {
      const roleIds = []
      this.candidateGroupsIdSet.forEach((crop, index, arr) => {
        roleIds.push(crop)
      })
      let number = 0
      let count = 0
      this.queryParam.roleIds = roleIds
      this.queryParam.corpId = this.workflowModel.corpId
      const requestParameters = Object.assign({}, this.queryParam)
      getWorkFlowUserByRoleIds(requestParameters).then((response) => {
        if (response.success) {
          count = response.obj.length
          number = count
          response.obj.forEach((user, index, arr) => {
            if (this.candidateUsersIdSet.has(user.id)) {
              number = number - 1
            }
          })
        }
        this.computeCandidateRoleUsersCount(number, count)
        this.$forceUpdate()
      })
    },
    /**
     * 【备选用户】点击事件
     */
    onAlternativeUserItemClick(user) {
      if (!user) {
        return
      }
      if (this.candidateUsersIdSet.has(user.id)) {
        this.removeCandidateUser(user)
      } else {
        this.addCandidateUser(user)
        this.currentCorpUsers = this.currentCorpUsers.filter(
          (list) => list.id !== user.id
        )
      }
    },
    /**
     * 添加用户为【审批人】
     */
    addCandidateUser(user) {
      if (!user) {
        return
      }
      if (!this.candidateUsersIdSet.has(user.id)) {
        user.isSelected = true
        this.candidateUsersIdSet.add(user.id)
        this.candidateUsers.push(user)
      }
      this.listUserByRoleIds()
    },
    /**
     * 移除指定的审批人
     */
    removeCandidateUser(user) {
      if (!user) {
        return false
      }
      if (this.currentCorpKeys !== [] && this.currentCorpKeys) {
        if (user.corpId && user.corpId === this.currentCorpKeys[0]) {
          this.currentCorpUsers.push(user)
        }
      }

      user.isSelected = false
      this.candidateUsersIdSet.delete(user.id)
      const candidateUsers = this.candidateUsers
      candidateUsers.splice(
        candidateUsers.findIndex((item) => item.id === user.id),
        1
      )
      this.candidateUsers = candidateUsers
      this.listUserByRoleIds()
    },
    onRoleItemClick(role) {
      if (!role) {
        return
      }
      const candidateGroupsIdSet = this.candidateGroupsIdSet
      this.candidateGroupsIdSet = candidateGroupsIdSet
      if (candidateGroupsIdSet.has(role.id)) {
        candidateGroupsIdSet.delete(role.id)
      } else {
        candidateGroupsIdSet.add(role.id)
      }
      this.listUserByRoleIds()
    },
    /**
     * 统计已经选中的可审批人员的数量
     */
    computeCandidateUsersCount() {
      const that = this
      // 统计已经选中的可审批人员的数量
      let candidateUsersCount = 0
      // 统计已经选中的用户数量
      candidateUsersCount += that.candidateUsersIdSet.size
      this.candidateUsersCount = candidateUsersCount
      // console.log('统计已经选中的可审批人员的数量：', candidateUsersCount)
    },
    /**
     * 统计已经选中角色的可审批人员的数量
     */
    computeCandidateRoleUsersCount(number, count) {
      const that = this
      // 统计已经选中的可审批人员的数量
      let candidateUsersCount = 0
      candidateUsersCount = that.candidateUsersIdSet.size + number
      this.candidateUsersCount = candidateUsersCount
      that.userTab = "按用户"
      that.roleUserTab = "按角色"
      if (this.candidateUsersIdSet.size > 0) {
        that.userTab =
          "按用户（已选择" + this.candidateUsersIdSet.size + " 人）"
      }
      if (count > 0) {
        that.roleUserTab = "按角色（已选择" + count + " 人）"
      }
      // console.log('统计已经选中的可审批人员的数量：', candidateUsersCount)
    },

    onCorpNodeClick(selectedKeys, e) {
      this.currentCorpKeys = selectedKeys
      this.getCorpUserList(selectedKeys)
    },

    onCorpSearchValueChange(e) {
      const value = e.target.value
      if (!value) {
        return
      }
      const that = this
      const expandedCorpKeys = that.corpTreeList
        .map((item) => {
          if (item.name.indexOf(value) > -1) {
            return getCorpParentId(item.id, that.corpTreeList)
          }
          return null
        })
        .filter((item, index, self) => {
          return item && self.indexOf(item) === index
        })
      that.expandedCorpKeys = expandedCorpKeys
      that.corpAutoExpandParent = true
    },

    onCorpExpand(expandedCorpKeys) {
      this.expandedCorpKeys = expandedCorpKeys
      this.corpAutoExpandParent = false
    },

    resetData() {
      this.element = null
      this.candidateType = "user"
      this.candidateUsers = []
      this.candidateGroups = []
      this.passNumber = 0

      this.roles = []

      this.corpTreeList = []
      this.expandedCorpKeys = []
      this.currentCorpKeys = null
      this.corpAutoExpandParent = true
      this.currentCorpUsers = []

      this.candidateGroupsIdSet.clear()
      this.candidateUsersIdSet.clear()
    },
  },
}
</script>

<style lang="less" scoped>
.ant-modal-body {
  padding: 5px 15px !important;
}

.list-select-user-active {
  background-color: #dff0d8;
}

