<script>
import events from './events'
// import { bxAnaalyse } from '@/core/icons'
import { i18nRender } from '@/locales'
const indexKey = '/index' // 首页
export default {
  name: 'MultiTab',
  data () {
    return {
      fullPathList: [],
      pages: [],
      activeKey: '',
      newTabIndex: 0
    }
  },
  created () {
    // bind event
    events
      .$on('open', (val) => {
        if (!val) {
          throw new Error(`multi-tab: open tab ${val} err`)
        }
        this.activeKey = val
      })
      .$on('close', (val) => {
        if (!val) {
          this.closeThat(this.activeKey)
          return
        }
        this.closeThat(val)
      })
      .$on('rename', ({ key, name }) => {
        try {
          const item = this.pages.find((item) => item.path === key)
          item.meta.customTitle = name
          this.$forceUpdate()
        } catch (e) {}
      })
    // 添加首页

    if (this.$route.fullPath !== indexKey) {
      this.addIndexToFirst()
    }
    this.pages.push(this.$route)
    this.fullPathList.push(this.$route.fullPath)
    this.selectedLastPath()
  },
  methods: {
    // 将首页添加到第一位
    addIndexToFirst () {
      this.pages.splice(0, 0, {
        name: 'index',
        path: indexKey,
        fullPath: indexKey,
        meta: {
          icon: '',
          title: '首页'
        }
      })
      this.fullPathList.splice(0, 0, indexKey)
    },
    onEdit (targetKey, action) {
      this[action](targetKey)
    },
    // 关闭的标签都清除掉缓存
    removeKeepAliveCache (targetKey) {
      const cs = this.$parent.$parent.$parent.$children
      // const targetThis = cs[cs.length - 1]
      // if (
      //   targetThis.$vnode.parent &&
      //   targetThis.$vnode.parent.componentInstance &&
      //   targetThis.$vnode.parent.componentInstance.cache
      // ) {
      //   if (targetThis.$vnode.componentOptions) {
      //     // var key =
      //     //   targetThis.$vnode.key == null
      //     //     ? targetThis.$vnode.componentOptions.Ctor.cid +
      //     //       (targetThis.$vnode.componentOptions.tag ? `::${targetThis.$vnode.componentOptions.tag}` : '')
      //     //     : targetThis.$vnode.key
      //     const key = targetKey
      //     var cache = targetThis.$vnode.parent.componentInstance.cache
      //     var keys = targetThis.$vnode.parent.componentInstance.keys
      //     if (cache[key]) {
      //       if (keys.length) {
      //         var index = keys.indexOf(key)
      //         if (index > -1) {
      //           keys.splice(index, 1)
      //         }
      //       }
      //       delete cache[key]
      //     }
      //   }
      // }
        // basicLayout组件中，添加了a-config-provider(解决下拉框时间框等定位的问题）,引起了层级的变化，造成手动清除缓存方法的更改
       // const targetThis = cs[cs.length - 2]
        const targetThis = cs[cs.length - 1]
        if (
            targetThis.$vnode.componentOptions &&
            targetThis.$vnode.componentOptions.children[0] &&
            targetThis.$vnode.componentOptions.children[0].children
        ) {
            const cs1 = targetThis.$vnode.componentOptions.children[0].children
            const currentTargetThis = cs1[cs1.length - 2]
            if (currentTargetThis.componentOptions.children[0] && currentTargetThis.componentOptions.children[0].parent && currentTargetThis.componentOptions.children[0].parent.componentInstance.cache) {
                const key = targetKey
                var cache = currentTargetThis.componentOptions.children[0].parent.componentInstance.cache
                var keys = currentTargetThis.componentOptions.children[0].parent.componentInstance.keys
                if (cache[key]) {
                    if (keys.length) {
                        var index = keys.indexOf(key)
                        if (index > -1) {
                            keys.splice(index, 1)
                        }
                    }
                    delete cache[key]
                }
            }
        }
      // targetThis.$destroy()
    },
    remove (targetKey) {
      this.pages = this.pages.filter((page) => page.fullPath !== targetKey)
      this.fullPathList = this.fullPathList.filter((path) => path !== targetKey)
      // ------------- 新增编辑弹窗关闭时 返回父页面的动作------------start
      const parentPath = this.$store.getters.asyncTabProps(targetKey)?.parentPath || null
      if (this.fullPathList.includes(parentPath)) {
        this.activeKey = parentPath
        // ------------- 新增编辑弹窗关闭时 返回父页面的动作------------end
      } else if (!this.fullPathList.includes(this.activeKey)) {
        // 判断当前标签是否关闭，若关闭则跳转到最后一个还存在的标签页
        this.selectedLastPath()
      } else {
        this.selectedLastPath()
      }
      this.removeKeepAliveCache(targetKey)
    },
    selectedLastPath () {
      this.activeKey = this.fullPathList[this.fullPathList.length - 1]
    },
    // content menu
    refresh (e) {
      this.$emit('refresh')
    },
    closeThat (e) {
      // 判断是否为最后一个标签页，如果是最后一个，则无法被关闭
      // 如果是首页，也不充许关闭
      if (this.fullPathList.length > 1 && indexKey !== e) {
        this.remove(e)
      } else {
        if (indexKey === e) {
          this.$message.info(this.$t('common.tab.noclose.home'))
        } else {
          this.$message.info(this.$t('common.tab.noclose.onlytab'))
        }
      }
    },
    closeLeft (e) {
      const currentIndex = this.fullPathList.indexOf(e)
      if (currentIndex > 0) {
        this.fullPathList.forEach((item, index) => {
          if (index < currentIndex && item !== indexKey) {
            this.remove(item)
          }
        })
      } else {
        this.$message.info(this.$t('common.tab.noclose.left'))
      }
    },
    closeRight (e) {
      const currentIndex = this.fullPathList.indexOf(e)
      if (currentIndex < this.fullPathList.length - 1) {
        this.fullPathList.forEach((item, index) => {
          if (index > currentIndex) {
            this.remove(item)
          }
        })
      } else {
        this.$message.info(this.$t('common.tab.noclose.right'))
      }
    },
      closeOthers (e) {
          const currentIndex = this.fullPathList.indexOf(e)
          if (currentIndex > 0) {
              this.fullPathList.forEach((item, index) => {
                  if (index !== currentIndex && item !== indexKey) {
                      this.remove(item)
                  }
              })
          } else {
              this.$message.info(this.$t('common.tab.noclose.others'))
          }
      },
    closeAll (e) {
      this.fullPathList.forEach((item, index) => {
        if (item !== indexKey) {
          this.remove(item)
        }
      })
      this.$router.push(indexKey)
    },
    closeMenuClick (key, route) {
      this[key](route)
    },
    renderTabPaneMenu (e) {
      return (
        <a-menu
        style="width:130px;"
          {...{
            on: {
              click: ({ key, item, domEvent }) => {
                this.closeMenuClick(key, e)
              }
            }
          }}
        >
          <a-menu-item key="refresh" class="context-item">
            {i18nRender('common.btn.refresh')}
          </a-menu-item>
          <a-menu-item key="closeThat" class="context-item">
            {i18nRender('common.tabs.closeCurrent')}
          </a-menu-item>
            <a-menu-item key="closeOthers" class="context-item">
                {i18nRender('common.tabs.closeOthers')}
            </a-menu-item>
          <a-menu-item key="closeAll" class="context-item">
            {i18nRender('common.tabs.closeAll')}
          </a-menu-item>
        </a-menu>
      )
    },
    // render
    renderTabPane (page, activeKey) {
      const { fullPath: keyPath } = page
      let title = page.meta.title || page.meta.newTitle
      // 特殊处理----------------------------------start
      // asyncTab title 的渲染与刷新处理
      if (page.name === 'commonEdit') {
        const moduleName = keyPath.substring(1).replace(/(\/)/g, '.')
        title = (this.$store.getters.asyncTabProps(keyPath) || JSON.parse(localStorage.getItem(moduleName))).title
      }
      // 特殊处理----------------------------------start
      if (keyPath === indexKey) { // 首页时，不需要右击功能
        return (
          <span
            style={{ userSelect: 'none', display: 'inline-block', padding: '0 10px' }}
          >
            {title}
          </span>
        )
      }
      const menu = this.renderTabPaneMenu(keyPath)

      return (
        <a-dropdown overlay={menu} trigger={['contextmenu']}>
          <span style={{ userSelect: 'none', display: 'inline-block', padding: '0 10px' }}>{title}</span>
        </a-dropdown>
      )
    }
  },
  watch: {
    $route: function (newVal) {
      this.activeKey = newVal.fullPath
      if (this.fullPathList.indexOf(newVal.fullPath) < 0) {
        this.fullPathList.push(newVal.fullPath)
        this.pages.push(newVal)
      }
    },
    activeKey: function (newPathKey) {
      this.$router.push({ path: newPathKey })
    },
    '$store.state.pages.removeTargetKey': {
      deep: true,
      handler: function (newVal, oldVal) {
        newVal && this.remove(newVal)
        this.$store.commit('SET_REMOVE_KEY', null)
      }
    }
  },
  render () {
    const {
      onEdit,
      $data: { pages }
    } = this
    const panes = pages.map((page) => {
      return (
        <a-tab-pane
          style={{ height: 0 }}
          tab={this.renderTabPane(page, this.activeKey)}
          key={page.fullPath}
          closable={page.fullPath !== '/index'}
        ></a-tab-pane>
      )
    })
    return (
      <div class={pages.length === 1 ? 'only-one ant-pro-multi-tab' : 'ant-pro-multi-tab'}>
        <div class="ant-pro-multi-tab-wrapper">
          <a-tabs
            hideAdd
            type={'editable-card'}
            v-model={this.activeKey}
            class="theme-tabs ui-layout-tabs"
            {...{ on: { edit: onEdit } }}
          >
            {panes}
          </a-tabs>
        </div>
      </div>
    )
  }
}
</script>
<style scoped lang="less">
    .ant-pro-multi-tab {
        margin-bottom: 0;
        width: 100%;
        background: #EDEDED;
        /deep/ .ant-tabs .ant-tabs-bar {
            background: #F3F3F3;
            height: 32px;
            padding-top: 0px;
            padding-left: 0px;
        }
        /deep/ .ant-tabs.ant-tabs-card .ant-tabs-card-bar .ant-tabs-nav-container {
            height: 32px;
            margin-top: 0px;
        }
        /deep/ .ant-tabs.ant-tabs-card .ant-tabs-card-bar .ant-tabs-tab {
            border-bottom: 0px solid transparent !important;
            height: 32px;
            padding: 0 0px !important;
            margin-right: 0px !important;
            background: inherit;
        }
        /deep/ .ant-tabs.ant-tabs-card .ant-tabs-card-bar .ant-tabs-tab span {
            padding: 0 20px !important;
        }
        /deep/ .ant-tabs.ant-tabs-card .ant-tabs-card-bar .ant-tabs-tab .ant-tabs-close-x {
            margin-left: 4px!important;
        }
        /deep/ .ant-tabs.ant-tabs-card .ant-tabs-card-bar .ant-tabs-tab.ant-tabs-tab-active {
            border-bottom-width:0px!important;
            height: 32px;
            background-color:#FFFFFF!important;
            border-radius: 8px 8px 0px 0px
        }
        /deep/ .ant-tabs.ant-tabs-card .ant-tabs-card-bar .ant-tabs-tab:first-child.ant-tabs-tab-active {
            background-color: #F9F9F9!important;
        }
        /deep/ .ant-tabs-nav .ant-tabs-tab:hover{
            color: #333;
            background-color: #F9F9F9!important;
        }
        /deep/ .ant-tabs-nav .ant-tabs-tab.ant-tabs-tab-active:hover{
            color: #4962E3;
            background-color:#FFFFFF!important;
        }
    }
    .only-one {
        /deep/ .ant-tabs.ant-tabs-card .ant-tabs-card-bar .ant-tabs-tab {
            display: none;
        }
    }
    .context-item {
        padding-left: 24px;
    }

</style>
