// input
export function getBaseInputConfig ({ config = {}, options = {} } = {}) {
  return Object.assign(
      {
          type: 'input',
          label: '输入框',
          icon: 'icon-write',
          options: Object.assign(
              {
                  type: 'text',
                  width: null,
                  defaultValue: '',
                  placeholder: '请输入',
                  clearable: false,
                  maxLength: null,
                  hidden: false,
                  disabled: false
              },
              options
          ),
          model: `group[i]fieldValue`,
          key: 'input_',
          rules: []
      },
      config
  )
}
