/**
 * 自定义组件的渲染配置
 *  customComponentName 的取值范围请查看 @\components\AsyncLoadCustomComponent.js的组件注册
 *  组件props根据组件而定，一般全部支持antd官方组件属性
 * @param {*}
 * @returns
 */
export function getCustomComponentConfig ({ config = {}, options = {} } = {}) {
/**
 * 配置建议
 *
 *
 ********** CorpTreeSelect 单选 **********
 * checkable: false,
 * defaultValue: '',
 **********  CorpTreeSelect 多选 **********
 * checkable: true,// 多选配置true
 * defaultValue: [],// 多选配置true
 *
 */

  return Object.assign(
      {
          type: 'customComponent', //  固定值
          label: '',
          customComponentName: '', // 组件名字 必填
          options: Object.assign(
              {
                  // 组件props
                  width: null
              },
              options
          ),
          model: '', // 必填
          help: '',
          rules: [{ required: true, message: '必填项' }]
      },
      config
  )
}

// 单选字典dictSelect
export function getDictSelectConfig ({ config = {}, options = {} } = {}) {
    return Object.assign(
        {
            type: 'DictSelect',
            label: '字典单选',
            options: Object.assign(
                {
                    defaultValue: '', // 默认值
                    hidden: false,
                    disabled: false, //  默认为false
                    placeholder: '请选择', // 占位符
                    type: '', // 声明类型
                    width: '100%',
                    dictGroup: ''
                },
                options
            ),
            model: 'dict',
            help: '',
            rules: [{ required: true, message: '必填项' }]
        },
        config
    )
}
