import request from "@/utils/request";

// 修改流程模型
export function updateModel(data) {
  return request({
    url: "/bpm/model/saveCustomer",
    method: "post",
    data: data,
  });
}

// 查询流程模型详细
export function getModel(id) {
  return request({
    url: "/bpm/model/" + id,
    method: "get",
  });
}
