<template>
  <div class="property-panel" ref="propertyPanel">
    <a-card
      :bordered="true"
      style="height: calc(100% - 12px); margin-top: 22px"
    >
      <h3>{{ getElementTitle }}</h3>
      <a-form-model
        :inline="true"
        :model="form"
        :label-col="labelCol"
        :wrapper-col="wrapperCol"
        :rules="rules"
        ref="refForm"
      >
        <template v-if="isStartEvent">
          <a-form-model-item
            hidden
            :label="$t('workflow.model.label.node.id')"
            prop="id"
          >
            <a-input v-model="form.id" disabled></a-input>
          </a-form-model-item>
          <a-form-model-item
            :label="$t('workflow.model.label.name')"
            prop="name"
          >
            <a-input v-model="form.name" @input="nameChange"></a-input>
          </a-form-model-item>
        </template>

        <template v-if="isUserTask">
          <a-row>
            <a-form-model-item
              hidden
              :label="$t('workflow.model.label.node.id')"
              prop="id"
            >
              <a-input v-model="form.id" disabled></a-input>
            </a-form-model-item>
          </a-row>
          <a-row>
            <a-form-model-item
              :label="$t('workflow.model.label.name')"
              prop="name"
            >
              <a-input v-model="form.name" @input="nameChange"></a-input>
            </a-form-model-item>
          </a-row>
          <a-row>
            <div style="height: 20px"></div>
            <a-button block @click="openCandidateModal"
              >{{ $t("workflow.model.title.approval.configuration") }}({{
                candidateUsersCount
              }})</a-button
            >
          </a-row>
        </template>
        <template v-if="isExclusiveGateway">
          <a-form-model-item
            hidden
            :label="$t('workflow.model.label.node.id')"
            prop="id"
          >
            <a-input v-model="form.id" disabled></a-input>
          </a-form-model-item>
          <a-form-model-item
            :label="$t('workflow.model.label.name')"
            prop="name"
          >
            <a-input v-model="form.name" @input="nameChange"></a-input>
          </a-form-model-item>
        </template>

        <template v-if="isSequenceFlow">
          <a-form-model-item
            hidden
            :label="$t('workflow.model.label.node.id')"
            prop="id"
          >
            <a-input v-model="form.id" disabled></a-input>
          </a-form-model-item>
          <a-form-model-item
            :label="$t('workflow.model.label.name')"
            prop="name"
          >
            <a-input v-model="form.name" @input="nameChange"></a-input>
          </a-form-model-item>
          <!-- 分支允许添加条件 -->
          <a-button
            block
            @click="addFlowConditions"
            style="margin-top: 20px; margin-bottom: 10px"
            >{{ $t("workflow.model.button.condition.setting") }}
          </a-button>
          <a-row>
            <a-col span="24">
              <label
                >{{
                  $t("workflow.model.label.sequential.flow.condition")
                }}:</label
              >
            </a-col>
            <a-col span="24">
              <div>
                <p v-if="!flowConditions.length">
                  {{ $t("workflow.model.message.not.condition") }}
                </p>
                <div>
                  <template v-for="(con, index) in flowConditions">
                    <span :key="index" style="margin-left: 5px">
                      {{ con.leftBracket2 ? "(" : "" }}
                      {{ con.leftBracket1 ? "(" : "" }}
                      {{ con.fieldLabel }}
                      {{ con.relationLabel }}
                      {{ con.fieldValueLabel }}
                      {{ con.rightBracket1 ? ")" : "" }}
                      {{ con.rightBracket2 ? ")" : "" }}
                      {{ con.conditionLabel }}
                    </span>
                  </template>
                </div>
              </div>
            </a-col>
          </a-row>
        </template>
        <template v-if="isEndEvent">
          <a-form-model-item
            hidden
            :label="$t('workflow.model.label.node.id')"
            prop="id"
          >
            <a-input v-model="form.id" disabled></a-input>
          </a-form-model-item>
          <a-form-model-item
            :label="$t('workflow.model.label.name')"
            prop="name"
          >
            <a-input v-model="form.name" @input="nameChange"></a-input>
          </a-form-model-item>
        </template>
      </a-form-model>
    </a-card>
    <config-candidate-modal
      ref="configCandidateModal"
      @ok="onCandidateModalVisibleOk"
    />
    <PropertyFlowConditionsModal
      :workflowModel="workflowModel"
      ref="flowConditionsModal"
      @conditions="getFlowConditions"
    />
  </div>
</template>

<script>
// 审批人员配置modal组件
import ConfigCandidateModal from "./ConfigCandidateModal"
import PropertyFlowConditionsModal from "@/views/flowDesigner/customPropertyPanel/PropertyFlowConditionsModal"
import { getWorkFlowUserByRoleIds } from "@/api/system/user/user"
function getDecode(str) {
  return decodeURIComponent(
    atob(str)
      .split("")
      .map(function (c) {
        return "%" + ("00" + c.charCodeAt(0).toString(16)).slice(-2)
      })
      .join("")
  )
}
// 获取顺序流元素内容
function getFlowConditions(values = []) {
  if (values[0]) {
    if (values[0].name === "flowConditions") {
      return JSON.parse(getDecode(values[0].value))
    } else if (values[0].values) {
      return getFlowConditions(values[0].values)
    } else {
      return []
    }
  }
}

export default {
  name: "CustomPropertyPanel",
  components: {
    ConfigCandidateModal,
    PropertyFlowConditionsModal,
  },
  props: {
    modeler: {
      type: Object,
      required: true,
    },
    workflowModel: {
      type: Object,
      required: true,
    },
  },
  created() {},
  computed: {
    isStartEvent() {
      if (!this.element) {
        return
      }
      return this.element.type === "bpmn:StartEvent"
    },
    isEndEvent() {
      if (!this.element) {
        return
      }
      return this.element.type === "bpmn:EndEvent"
    },
    isUserTask() {
      if (!this.element) {
        return
      }
      return this.element.type === "bpmn:UserTask"
    },
    isSequenceFlow() {
      if (!this.element) {
        return
      }
      return this.element.type === "bpmn:SequenceFlow"
    },
    isExclusiveGateway() {
      if (!this.element) {
        return
      }
      return this.element.type === "bpmn:ExclusiveGateway"
    },
    getElementTitle() {
      if (!this.element) {
        return ""
      }
      const elementType = this.element.type
      let title = ""
      switch (elementType) {
        case "bpmn:UserTask":
          title = this.$t("workflow.model.title.userTask")
          break
        case "bpmn:SequenceFlow":
          title = this.$t("workflow.model.title.sequenceFlow")
          break
        case "bpmn:StartEvent":
          title = this.$t("workflow.model.title.startEvent")
          break
        case "bpmn:EndEvent":
          title = this.$t("workflow.model.title.endEvent")
          break
        case "bpmn:ExclusiveGateway":
          title = this.$t("workflow.model.title.exclusiveGateway")
          break
        default:
          title = ""
          break
      }
      return title
    },
  },
  data() {
    return {
      form: {
        id: "",
        name: "",
        color: null,
      },
      processElement: null,
      labelCol: { span: 6 },
      wrapperCol: { span: 16 },
      element: {},
      queryParam: {},
      candidateUsersCount: 0,
      flowConditions: [],
      rules: {
        name: [
          {
            required: true,
            message: "请输入" + this.$t("workflow.model.label.name"),
            trigger: "blur",
          },
        ],
      },
    }
  },
  async mounted() {
    this.handleModeler()
    this.handleEventBug()
  },
  methods: {
    // 字符串转base64
    getEncode64(str) {
      return btoa(
        encodeURIComponent(str).replace(
          /%([0-9A-F]{2})/g,
          function toSolidBytes(match, p1) {
            return String.fromCharCode("0x" + p1)
          }
        )
      )
    },
    handleModeler() {
      // 监听节点选择变化
      this.modeler.on("selection.changed", (e) => {
        const element = e.newSelection[0]
        if (!element) {
          return
        }
        this.element = element
        this.form = {
          ...element.businessObject,
          ...element.businessObject.$attrs,
        }
        // 当点击是顺序流时，要检查顺序流里面的内容
        this.flowConditions = []
        if (element.businessObject.extensionElements) {
          this.flowConditions = getFlowConditions(
            element.businessObject.extensionElements.values
          )
        }
        this.listUserByRoleIds()
      })

      //  监听节点属性变化
      this.modeler.on("element.changed", (e) => {
        const { element } = e
        if (!element) {
          return
        }
        //  新增节点需要更新回属性面板
        if (element.id === this.form.id) {
          this.form.name = element.businessObject.name
          this.form = { ...this.form }
        }
      })
    },

    handleEventBug() {
      const eventBus = this.modeler.get("eventBus")
      // 注册节点事件，eventTypes中可以写多个事件
      // const eventTypes = ['element.click', 'element.hover'];
      const eventTypes = ["element.click"]
      eventTypes.forEach((eventType) => {
        eventBus.on(eventType, (e) => {
          const { element } = e
          if (!e || element.type === "bpmn:Process") {
            if (!this.processElement) {
              this.processElement = element
            }
            return false
          }
        })
      })
    },

    /**
     * 属性面板名称，更新回流程节点
     */
    nameChange(event) {
      if (this.form.name) {
        const modeling = this.modeler.get("modeling")
        modeling.updateLabel(this.element, this.form.name)
      } else {
        const modeling = this.modeler.get("modeling")
        modeling.updateLabel(this.element, null)
      }
    },
    /**
     * 属性面板颜色，更新回流程节点
     */
    colorChange(color) {
      const modeling = this.modeler.get("modeling")
      modeling.setColor(this.element, {
        fill: null,
        stroke: color,
      })
      modeling.updateProperties(this.element, { color: color })
    },
    /**
     * 任务节点配置人员
     */
    addUser(properties) {
      this.updateProperties(
        Object.assign(properties, {
          // userType: Object.keys(properties)[0],
        })
      )
    },
    /**
     * 【最少审批人数】配置
     */
    updatePassNumber(passNumber) {
      // do not allow on root element
      const element = this.element
      if (!element) {
        return
      }
      const businessObject = element.businessObject

      const moddle = this.modeler.get("moddle")
      // 获取/创建扩展元素
      businessObject.extensionElements =
        businessObject.extensionElements ||
        moddle.create("bpmn:ExtensionElements")
      if (!businessObject.extensionElements.values) {
        businessObject.extensionElements.values = []
      }
      businessObject.extensionElements.$parent = element

      // 创建/更新自定义属性元素
      const extensionElementValues = businessObject.extensionElements.values
      let updateFlag = false
      extensionElementValues &&
        extensionElementValues.forEach((extensionElementValue, index, arr) => {
          if (extensionElementValue.$type === "camunda:Properties") {
            const propertiesValues = extensionElementValue.values
            if (propertiesValues) {
              for (let i = 0, size = propertiesValues.length; i < size; i++) {
                if (
                  propertiesValues[i].$type === "camunda:Property" &&
                  propertiesValues[i].name === "passNumber"
                ) {
                  // 更新最少审批人数配置
                  propertiesValues[i].value = passNumber
                  updateFlag = true
                  break
                }
              }
            }
          }
        })
      if (!updateFlag) {
        let hasProperties = false
        for (let i = 0, size = extensionElementValues.length; i < size; i++) {
          if (extensionElementValues[i].$type === "camunda:Properties") {
            hasProperties = true
            break
          }
        }
        if (!hasProperties) {
          // 创建最少审批人数配置
          const passNumberPropertie = moddle.create("camunda:Property")
          passNumberPropertie.name = "passNumber"
          passNumberPropertie.value = passNumber

          // 扩展元素没有camunda:Properties元素，这里创建一个
          const propertiesElement = moddle.create("camunda:Properties")
          propertiesElement.values = []
          propertiesElement.values.push(passNumberPropertie)
          extensionElementValues.push(propertiesElement)
        }
      }
    },
    // 切换人员类型
    typeChange() {
      const types = ["assignee", "candidateUsers", "candidateGroups"]
      types.forEach((type) => {
        delete this.element.businessObject.$attrs[type]
        delete this.form[type]
      })
    },
    // 通用的更新节点属性的方法
    updateProperties(properties) {
      const modeling = this.modeler.get("modeling")
      modeling.updateProperties(this.element, properties)
    },

    openCandidateModal() {
      this.$refs.configCandidateModal.showModal(
        this.workflowModel,
        this.element,
        this.form
      )
    },
    /**
     * 查询角色下员工信息
     */
    listUserByRoleIds() {
      const candidateUsersIdSet = new Set()
      let number = 0
      if (this.form["candidateUsers"]) {
        const candidateUser = this.form["candidateUsers"].split(",") || []
        candidateUser.forEach((user, index, arr) => {
          candidateUsersIdSet.add(user)
        })
      }
      if (this.form["candidateGroups"]) {
        const roleIds = []
        const candidateGroups = this.form["candidateGroups"].split(",") || []
        candidateGroups.forEach((crop, index, arr) => {
          roleIds.push(crop)
        })
        this.queryParam.roleIds = roleIds
        this.queryParam.corpId = this.workflowModel.corpId
        const requestParameters = Object.assign({}, this.queryParam)
        getWorkFlowUserByRoleIds(requestParameters).then((response) => {
          if (response.success) {
            number = response.obj.length
            response.obj.forEach((user, index, arr) => {
              if (candidateUsersIdSet.has(user.id)) {
                number = number - 1
              }
            })
            this.candidateUsersCount = candidateUsersIdSet.size + number
          }
        })
      } else {
        this.candidateUsersCount = candidateUsersIdSet.size
      }
    },
    /**
     * 审批人员配置 - 确认事件
     */
    onCandidateModalVisibleOk(candidateData) {
      const {
        candidateGroups,
        candidateUsersIds,
        candidateUsersCount,
        passNumber,
      } = candidateData

      // 更新【审批角色】属性
      let updatedCandidateGroups = ""
      if (candidateGroups && candidateGroups.length > 0) {
        updatedCandidateGroups = candidateGroups.join(",")
      }
      this.addUser({ candidateGroups: updatedCandidateGroups })
      this.form.candidateGroups = updatedCandidateGroups

      // 更新【审批用户】属性
      let updatedCandidateUsers = ""
      if (candidateUsersIds && candidateUsersIds.length > 0) {
        updatedCandidateUsers = candidateUsersIds.join(",")
      }
      this.addUser({ candidateUsers: updatedCandidateUsers })
      this.form.candidateUsers = updatedCandidateUsers

      // 更新【最少审批人数】属性
      this.updatePassNumber(passNumber)
      this.form.passNumber = passNumber
      this.candidateUsersCount = candidateUsersCount
    },
    // 打开条件
    addFlowConditions() {
      this.$refs.flowConditionsModal.open(
        this.element,
        this.form,
        this.flowConditions
      )
    },
    // 获取顺序流条件规则：更新顺序流条件
    getFlowConditions(options, expression) {
      this.flowConditions = options
      if (expression) {
        // console.log('expression', expression)
        const newConditionElement = this.modeler
          .get("moddle")
          .create("bpmn:FormalExpression", { body: expression })
        this.updateProperties({ conditionExpression: newConditionElement })
      } else {
        this.updateProperties({ conditionExpression: null })
      }
      this.updateFlowConditions(options)
    },
    // 更新顺序流信息
    updateFlowConditions(condition) {
      // do not allow on root element
      const element = this.element
      if (!element) {
      }
      const businessObject = element.businessObject

      const moddle = this.modeler.get("moddle")
      // 获取/创建扩展元素
      businessObject.extensionElements =
        businessObject.extensionElements ||
        moddle.create("bpmn:ExtensionElements")
      if (!businessObject.extensionElements.values) {
        businessObject.extensionElements.values = []
      }
      businessObject.extensionElements.$parent = element
      // 创建/更新自定义属性元素
      const extensionElementValues = businessObject.extensionElements.values
      let updateFlag = false
      if (
        extensionElementValues.length &&
        extensionElementValues[0].$type === "camunda:Properties"
      ) {
        const propertiesValues = extensionElementValues[0].values
        if (propertiesValues) {
          for (let i = 0, size = propertiesValues.length; i < size; i++) {
            if (
              propertiesValues[i].$type === "camunda:Property" &&
              propertiesValues[i].name === "flowConditions"
            ) {
              // 更新顺序流信息
              // propertiesValues[i].value = JSON.stringify(condition)
              propertiesValues[i].value = this.getEncode64(
                JSON.stringify(condition)
              )
              updateFlag = true
              break
            }
          }
        }
      }
      if (!updateFlag) {
        let hasProperties = false
        if (
          extensionElementValues.length &&
          extensionElementValues[0].$type === "camunda:Properties"
        ) {
          hasProperties = true
        }
        if (!hasProperties) {
          // 创建流程条件配置
          const flowConditionProperty = moddle.create("camunda:Property", {
            name: "flowConditions",
            // base64编码，解决XML转义字符的问题
            value: this.getEncode64(JSON.stringify(condition)),
          })
          // flowConditionProperty.name = 'flowConditions'
          // flowConditionProperty.value = JSON.stringify(condition)
          // flowConditionProperty.body = JSON.stringify(condition)
          // 扩展元素没有camunda:Properties元素，这里创建一个
          const propertiesElement = moddle.create("camunda:Properties")
          propertiesElement.values = []
          propertiesElement.values.push(flowConditionProperty)
          extensionElementValues.push(propertiesElement)
        }
      }
    },
  },
}
</script>

<style lang="less" scoped>
.property-panel {
  position: absolute;
  right: 0px;
  top: 0px;
  //border-left: 1px solid #cccccc;
  padding: 20px 0;
  width: 320px;
  height: 100%;
  padding: 10px;
}
</style>
