import Vue from "vue";
import App from "./App.vue";
import router from "./router";
import store from "./store";
import Storage from "vue-ls";
import { Icon } from "ant-design-vue";
import i18n from "./locales";
import bootstrap from "./core/bootstrap";
import "./core/lazy_use"; // use lazy load components

import iconFonts from "@/assets/iconfonts/iconfont";
import KFormItem from "@/components/FormDesign/KFormItem";
const BtIcon = Icon.createFromIconfontCN({
  scriptUrl: iconFonts,
});

const options = {
  namespace: "vuejs__", // key键前缀
  name: "ls", // 命名Vue变量.[ls]或this.[$ls],
  storage: "session", // 存储名称: session, local, memory
};

Vue.component("bt-icon", BtIcon);
Vue.component("KFormItem", KFormItem);
Vue.use(Storage, options);
Vue.config.productionTip = false;

new Vue({
  router,
  i18n,
  store,
  created: bootstrap,
  render: (h) => h(App),
}).$mount("#app");
